typedef struct c {
    float a, b; } complex;

complex prod(complex c1, complex c2)
{
    complex c3;
    c3.a = c1.a*c2.a-c1.b*c2.b;
    c3.b = c1.a*c2.b+c2.a*c1.b;
    return c3;
}

int main(void)
{
    complex c1, c2, c3;
    c3 = prod(c1, c2);
    return 0;
